contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: takes an amount to deposit and then attempts withdrawAll
    function run(uint depositAmount) public payable {
        // To send Ether to c, ensure this contract holds enough
        require(address(this).balance >= depositAmount);

        // Read c's balance before any operations
        uint cBalBefore = address(c).balance;

        // Deposit depositAmount into c from this contract
        c.deposit{value: depositAmount}();

        // After deposit, the c's balance should have increased by depositAmount
        uint cBalAfterDeposit = address(c).balance;

        // Now attempt to withdrawAll: since msg.sender for c calls is this test contract,
        // we expect c to try to send back the recorded credit for this contract.
        bool reverted;
        uint thisBalBeforeWithdraw = address(this).balance;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe c's balance after withdraw attempt
        uint cBalAfter = address(c).balance;

        // There's no public getter for credit mapping, but behavior observable through balances:
        // If withdrawAll succeeded (not reverted) then c's balance must have decreased by exactly depositAmount
        // and this contract's balance must have increased by that same amount.
        // If withdrawAll reverted then c's balance must be unchanged from after deposit.
        if (!reverted) {
            assert(cBalAfter + depositAmount == cBalAfterDeposit);
            assert(address(this).balance == thisBalBeforeWithdraw + depositAmount);
        } else {
            assert(cBalAfter == cBalAfterDeposit);
            assert(address(this).balance == thisBalBeforeWithdraw);
        }
    }

    // allow receiving ether from c when withdrawAll sends funds
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take two parameters: depositAmount to send to deposit(), and a flag doWithdraw
    // If doWithdraw==true we call withdrawAll after depositing; otherwise we only deposit.
    function run(uint depositAmount, bool doWithdraw) public payable {
        require(address(this).balance >= depositAmount);

        // Record c's observable balance before any operation
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        // perform a deposit into c as this contract
        c.deposit{value: depositAmount}();

        // After deposit, c's balance must have increased by depositAmount
        uint afterDepositC = address(c).balance;
        // Now optionally attempt withdrawAll.
        bool withdrew = false;
        bool reverted = false;
        if (doWithdraw) {
            try c.withdrawAll() {
                withdrew = true;
            } catch {
                reverted = true;
            }
        }

        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;

        // General rule asserted:
        // 1) If withdrawAll was called and did not revert, then this contract's observable balance after the call
        //    is >= its observable balance before the deposit (i.e., it recovered at least what it deposited). This
        //    avoids relying on internal credit getters; it states that a successful withdrawAll cannot make the caller
        //    strictly poorer than before the deposit+withdraw sequence.
        // 2) If withdrawAll reverted then c's observable balance did not change as a result of the withdraw attempt.
        // 3) If withdrawAll was not called, balances reflect only the deposit.
        assert(
            // Case: withdraw attempted and succeeded
            (doWithdraw && !reverted && afterThis >= beforeThis)
            // Case: withdraw attempted and reverted -> c balance unchanged by withdraw attempt
            || (doWithdraw && reverted && afterC == afterDepositC)
            // Case: no withdraw attempted -> c balance equals afterDepositC and this balance decreased by depositAmount
            || (!doWithdraw && afterC == afterDepositC && afterThis + depositAmount == beforeThis)
        );
    }

    // allow receiving Ether from C during withdrawAll
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // depositAmount: amount to send into c via deposit()
    // doWithdraw: whether to call withdrawAll after deposit
    function run(uint depositAmount, bool doWithdraw) public payable {
        require(address(this).balance >= depositAmount);

        // record balances before any operations
        uint beforeThis = address(this).balance;
        uint beforeC = address(c).balance;

        // perform deposit into c
        c.deposit{value: depositAmount}();

        // record balances after deposit
        uint afterDepositThis = address(this).balance;
        uint afterDepositC = address(c).balance;

        // prepare variables for withdraw outcome
        bool withdrew = false;
        bool withdrewReverted = false;

        // call withdrawAll as a top-level statement if requested
        if (doWithdraw) {
            try c.withdrawAll() {
                withdrew = true;
            } catch {
                withdrewReverted = true;
            }
        }

        // record balances after possible withdraw
        uint finalThis = address(this).balance;
        uint finalC = address(c).balance;

        // Assert the general rule:
        // - If we called withdrawAll and it succeeded, this contract's final balance is >= its balance after deposit (i.e., it recovered at least what it deposited).
        // - If we called withdrawAll and it reverted, then c's observable balance is unchanged by the withdraw attempt (finalC == afterDepositC).
        // - If we did not call withdrawAll, balances reflect only the deposit: c increased by depositAmount and this decreased by depositAmount.
        assert(
            (doWithdraw && withdrew && finalThis >= afterDepositThis)
            || (doWithdraw && withdrewReverted && finalC == afterDepositC)
            || (!doWithdraw && finalC == afterDepositC && finalThis + depositAmount == beforeThis)
        );
    }

    // allow receiving Ether from C during withdrawAll
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // depositAmount: amount to send into c via deposit()
    // callWithdraw: whether to call withdrawAll after deposit
    function run(uint depositAmount, bool callWithdraw) public payable {
        require(address(this).balance >= depositAmount);

        // balances before any operations
        uint beforeThis = address(this).balance;
        uint beforeC = address(c).balance;

        // perform deposit into c as a top-level state-changing call
        c.deposit{value: depositAmount}();

        // balances after deposit
        uint afterDepositThis = address(this).balance;
        uint afterDepositC = address(c).balance;

        // perform withdrawAll as a top-level statement if requested, capturing revert
        bool withdrew = false;
        bool reverted = false;
        if (callWithdraw) {
            try c.withdrawAll() {
                withdrew = true;
            } catch {
                reverted = true;
            }
        }

        // balances after possible withdraw
        uint finalThis = address(this).balance;
        uint finalC = address(c).balance;

        // General rule asserted:
        // - If we called withdrawAll and it succeeded, then (1) this contract's balance increased by exactly the decrease in c's balance produced by the withdraw
        //   and (2) that decrease equals the amount that was paid out (i.e., finalThis - afterDepositThis == afterDepositC - finalC).
        // - If we called withdrawAll and it reverted, then c's observable balance is unchanged by the withdraw attempt (finalC == afterDepositC).
        // - If we did not call withdrawAll, balances reflect only the deposit.
        assert(
            (callWithdraw && withdrew && (finalThis - afterDepositThis == afterDepositC - finalC) && (afterDepositC - finalC >= 0))
            || (callWithdraw && reverted && finalC == afterDepositC)
            || (!callWithdraw && finalC == afterDepositC && finalThis + depositAmount == beforeThis)
        );
    }

    // allow receiving Ether from C during withdrawAll
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function: deposit some amount, then attempt withdrawAll.
    // Parameters: depositAmount to send to c, and a flag whether to call withdrawAll.
    function run(uint depositAmount, bool doWithdraw) public payable {
        // Ensure this contract has enough Ether to deposit when requested.
        if (depositAmount > 0) {
            require(address(this).balance >= depositAmount);
            c.deposit{value: depositAmount}();
        }

        // Observe contract balance before withdraw attempt
        uint balBefore = address(c).balance;

        // Try withdrawAll and record whether it reverted
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfter = address(c).balance;

        // Also try to observe whether this contract's credit (as recorded by C) is now zero

        // C has no public getter for credit, so we infer via behavior: if withdrawAll did not revert
        // and the contract's balance decreased, then the caller's recorded credit must now be 0.

        // General rule asserted:
        // 1) withdrawAll never increases address(c).balance (balAfter <= balBefore)
        // 2) If withdrawAll returned successfully (not reverted) then either balance decreased
        //    by some amount x and that caller's credit is now cleared (inferred), or it stayed the same
        //    (nothing to withdraw). We assert the observable part: balAfter <= balBefore, and
        //    if not reverted and balAfter < balBefore then true (credit was withdrawn).

        // The assert encodes that balAfter is never greater than balBefore, and that if withdraw did
        // not revert then either balance stayed the same or decreased.
        assert(balAfter <= balBefore && (!reverted ? (balAfter <= balBefore) : true));
    }

    receive() external payable {}
}
